const results = [];
for (const item of $input.all()) {
  try {

    const j = item.json;
    if (!j || !j.id || !j.position) continue;
    results.push({
      job_title: j.position || '',
      company: j.company || '',
      job_url: j.url || j.apply_url || ('https://remoteok.com' + (j.slug ? '/remote-jobs/' + j.slug : '')),
      source: 'Remote OK',
      location_text: j.location || 'Worldwide',
      salary: (j.salary_min && j.salary_max) ? `${j.salary_min}-${j.salary_max}` : (j.salary || ''),
      description: (j.description || '').toString(),
      posted_date: j.date || '',
      tags: Array.isArray(j.tags) ? j.tags.join(', ') : '',
    });

  } catch (e) {
    // skip malformed record, keep pipeline alive
  }
}
return results.map(r => ({ json: r }));

const results = [];
for (const item of $input.all()) {
  try {

    const body = item.json;
    const jobs = body.jobs || (Array.isArray(body) ? body : []);
    for (const j of jobs) {
      results.push({
        job_title: j.title || '',
        company: j.company_name || '',
        job_url: j.url || '',
        source: 'Remotive',
        location_text: j.candidate_required_location || 'Worldwide',
        salary: j.salary || '',
        description: (j.description || '').toString(),
        posted_date: j.publication_date || '',
        tags: Array.isArray(j.tags) ? j.tags.join(', ') : (j.category || ''),
      });
    }

  } catch (e) {
    // skip malformed record, keep pipeline alive
  }
}
return results.map(r => ({ json: r }));

const results = [];
for (const item of $input.all()) {
  try {

    const j = item.json;
    const titleParts = (j.title || '').split(':');
    results.push({
      job_title: titleParts.length > 1 ? titleParts.slice(1).join(':').trim() : (j.title || ''),
