      description: (j.contentSnippet || j.content || '').toString(),
      posted_date: j.pubDate || j.isoDate || '',
      tags: Array.isArray(j.categories) ? j.categories.join(', ') : '',
    });

  } catch (e) {
    // skip malformed record, keep pipeline alive
  }
}
return results.map(r => ({ json: r }));

const results = [];
for (const item of $input.all()) {
  try {

    const body = item.json;
    const jobs = body.jobs || (Array.isArray(body) ? body : []);
    for (const j of jobs) {
      if (!j || (!j.title && !j.slug)) continue;
      results.push({
        job_title: j.title || '',
        company: (j.companyName || (j.company && j.company.name)) || '',
        job_url: j.applicationLink || j.guid || (j.slug ? `https://himalayas.app/jobs/${j.slug}` : ''),
        source: 'Himalayas',
        location_text: (j.locationRestrictions && j.locationRestrictions.join(', ')) || 'Worldwide',
        salary: j.minSalary && j.maxSalary ? `${j.minSalary}-${j.maxSalary}` : '',
        description: (j.description || j.excerpt || '').toString(),
        posted_date: j.pubDate || j.publishedAt || '',
        tags: Array.isArray(j.categories) ? j.categories.join(', ') : '',
      });
    }

  } catch (e) {
    // skip malformed record, keep pipeline alive
  }
}
return results.map(r => ({ json: r }));

