const KEYWORDS = ["async remote", "asynchronous remote", "worldwide remote", "global remote", "work from anywhere", "remote data analyst", "remote data scientist", "remote ai marketing", "remote marketing analyst", "remote growth analyst", "remote bi analyst", "remote automation specialist", "remote ai workflow consultant"];
const items = $input.all();
const kept = items.filter(item => {
  const j = item.json;
  const haystack = `${j.job_title || ''} ${j.description || ''} ${j.tags || ''}`.toLowerCase();
  return KEYWORDS.some(k => haystack.includes(k));
});
return kept;

// New candidate jobs come from the Keyword Match Filter node (referenced by name,
// since this node's own input is the Google Sheets read of existing rows).
const newJobs = $('Keyword Match Filter').all();
const existingRows = $input.all().map(i => i.json);
const existingUrls = new Set(existingRows.map(r => (r.job_url || '').trim()));
const existingKeys = new Set(existingRows.map(r => `${(r.company||'').trim().toLowerCase()}|${(r.job_title||'').trim().toLowerCase()}`));

const seenThisRun = new Set();
const unique = [];
for (const item of newJobs) {
  const j = item.json;
  const url = (j.job_url || '').trim();
  const key = `${(j.company||'').trim().toLowerCase()}|${(j.job_title||'').trim().toLowerCase()}`;
  if (!url) continue;
  if (existingUrls.has(url) || existingKeys.has(key)) continue;
  if (seenThisRun.has(url) || seenThisRun.has(key)) continue;
  seenThisRun.add(url);
  seenThisRun.add(key);
  j.job_id = Buffer.from(url).toString('base64').slice(0, 24);
  j.date_found = new Date().toISOString().slice(0, 10);
  unique.push({ json: j });
}
return unique;

const REJECT_PHRASES = [
  'us only', 'canada only', 'uk only', 'eu only', 'europe only', 'australia only',
  'must be based in', 'must live in', 'must be authorized to work in',
  'local work permit required', 'hybrid', 'onsite', 'office required',
  'remote within country only', 'fixed us hours', 'fixed eu hours',
];
const KEEP_PHRASES = [
  'worldwide remote', 'global remote', 'work from anywhere', 'anywhere',
  'apac remote', 'international contractors accepted', 'contractor role',
  'b2b contractor', 'hires via deel', 'hires via remote.com', 'hires via oyster',
  'eor supported', 'remote first', 'distributed team',
];

const j = $input.item.json;
const text = `${j.job_title || ''} ${j.description || ''} ${j.location_text || ''}`.toLowerCase();

const matchedReject = REJECT_PHRASES.filter(p => text.includes(p));
const matchedKeep = KEEP_PHRASES.filter(p => text.includes(p));

// Keep-list overrides reject-list: a post can mention "office" once and still be
// globally remote. Only reject when nothing in the keep-list rescues it.
let hard_filter_pass = true;
let reject_category = '';
if (matchedKeep.length > 0) {
  hard_filter_pass = true;
} else if (matchedReject.length > 0) {
  hard_filter_pass = false;
  const r = matchedReject[0];
  if (r.includes('us only') || r.includes('fixed us')) reject_category = 'us_only';
  else if (r.includes('canada only')) reject_category = 'us_only';
  else if (r.includes('uk only')) reject_category = 'eu_only';
  else if (r.includes('eu only') || r.includes('europe only') || r.includes('fixed eu')) reject_category = 'eu_only';
  else if (r.includes('australia only')) reject_category = 'other_country_only';
  else if (r.includes('hybrid') || r.includes('onsite') || r.includes('office') || r.includes('within country')) reject_category = 'hybrid';
  else reject_category = 'other_country_only';
}

j.hard_filter_pass = hard_filter_pass;
j.hard_filter_matched_keep = matchedKeep.join(', ');
j.hard_filter_matched_reject = matchedReject.join(', ');
j.reject_category = reject_category;
return { json: j };

const j = $input.item.json;
j.date_rejected = new Date().toISOString().slice(0, 10);
j.reason = `Hard filter: matched "${j.hard_filter_matched_reject}"`;
j.reject_category = j.reject_category || 'other_country_only';
return { json: j };

const j = $input.item.json;
let parsed = { taiwan_eligible: 'unclear', reason: 'AI response unparseable', location_risk: 'medium', timezone_risk: 'medium', contractor_possible: 'unclear', decision: 'manual_check' };
try {
  const raw = j.content && j.content[0] && j.content[0].text ? j.content[0].text : '';
  const match = raw.match(/\{[\s\S]*\}/);
  if (match) parsed = JSON.parse(match[0]);
} catch (e) {
  // keep fallback 'manual_check' so a parsing hiccup never silently drops a job
}
j.taiwan_eligible = parsed.taiwan_eligible;
j.taiwan_reason = parsed.reason;
j.location_risk = parsed.location_risk;
j.timezone_risk = parsed.timezone_risk;
j.contractor_possible = parsed.contractor_possible;
j.ai_decision = parsed.decision;
return { json: j };

const j = $input.item.json;
j.date_rejected = new Date().toISOString().slice(0, 10);
j.reason = `AI eligibility: ${j.taiwan_reason || 'rejected'}`;
if (!j.reject_category) {
  if (j.location_risk === 'high') j.reject_category = 'other_country_only';
  else if (j.timezone_risk === 'high') j.reject_category = 'timezone';
  else j.reject_category = 'other_country_only';
}
return { json: j };

const POSITIVE = ['async', 'asynchronous', 'flexible hours', 'flexible schedule',
  'distributed team', 'remote first', 'low meeting culture', 'work across time zones'];
const NEGATIVE = ['strict 9 to 5', 'strict 9-to-5', 'fixed us hours', 'fixed est hours',
  'fixed pst hours', 'fixed cet hours', 'daily live calls required', 'must overlap full business day'];

const j = $input.item.json;
const text = `${j.job_title || ''} ${j.description || ''}`.toLowerCase();
const pos = POSITIVE.filter(p => text.includes(p));
const neg = NEGATIVE.filter(p => text.includes(p));

let async_pass = neg.length === 0;
let async_level = 'unclear';
if (pos.some(p => p.includes('async'))) async_level = 'high';
else if (pos.some(p => p.includes('flexible'))) async_level = 'medium';
else if (pos.length > 0) async_level = 'medium';
else async_level = j.timezone_risk === 'low' ? 'medium' : 'unclear';

j.async_pass = async_pass;
j.async_level = async_level;
j.async_matched_positive = pos.join(', ');
j.async_matched_negative = neg.join(', ');
return { json: j };

const j = $input.item.json;
j.date_rejected = new Date().toISOString().slice(0, 10);
j.reason = `Async/timezone: matched "${j.async_matched_negative}"`;
j.reject_category = 'timezone';
return { json: j };

const CORE_ROLES = ['data analyst', 'data scientist', 'junior data scientist',
  'business intelligence analyst', 'bi analyst', 'marketing analyst',
  'performance marketing analyst', 'growth analyst', 'ai marketing specialist',
  'ai automation specialist', 'ai workflow consultant', 'creative strategist',
  'martech analyst'];

const j = $input.item.json;
const text = `${j.job_title || ''} ${j.description || ''}`.toLowerCase();
const matched = CORE_ROLES.filter(r => text.includes(r));

j.role_category = matched.length ? matched[0] : 'general remote';
j.role_match = matched.length > 0 ? 'core' : 'adjacent';
return { json: j };

const j = $input.item.json;
let score = 0;

// Taiwan eligibility (max 40)
const kw = (j.hard_filter_matched_keep || '').toLowerCase();
if (j.taiwan_eligible === 'yes' && (kw.includes('worldwide') || kw.includes('work from anywhere') || kw.includes('global') || j.contractor_possible === 'yes')) {
  score += 40;
} else if (kw.includes('apac')) {
  score += 30;
} else if (j.taiwan_eligible === 'unclear' && j.location_risk !== 'high') {
  score += 20;
} else if (j.location_risk === 'high' || j.taiwan_eligible === 'no') {
  score += 0;
} else {
  score += 20;
}

// Async fit (max 25, take best matching tier only)
if (j.async_level === 'high') score += 25;
else if (j.async_level === 'medium' && (j.async_matched_positive || '').includes('flexible')) score += 20;
else if ((j.async_matched_positive || '').includes('distributed team')) score += 15;
else if ((j.async_matched_positive || '').includes('remote first')) score += 10;

// Role fit (max 25)
score += j.role_match === 'core' ? 25 : 15;

// Salary fit (max 25, take highest tier only)
const salaryText = (j.salary || '').replace(/[^0-9\-]/g, ' ');
const nums = salaryText.split(/\s+/).map(Number).filter(n => !isNaN(n) && n > 0);
const maxSalaryMonthly = nums.length ? Math.max(...nums) / (Math.max(...nums) > 20000 ? 12 : 1) : 0;
if (maxSalaryMonthly > 5000) score += 25;
else if (maxSalaryMonthly > 3000) score += 15;
else if (nums.length) score += 10;

j.total_score = Math.min(100, score);
return { json: j };

const j = $input.item.json;
j.date_rejected = new Date().toISOString().slice(0, 10);
j.reason = `Score ${j.total_score} below 70 threshold`;
j.reject_category = 'low_score';
return { json: j };

const j = $input.item.json;
const asyncOk = j.async_level === 'high' || j.async_level === 'medium';
const locationOk = j.location_risk === 'low';
const timezoneOk = j.timezone_risk === 'low' || j.timezone_risk === 'medium';

if (j.taiwan_eligible === 'yes' && j.total_score >= 85 && asyncOk && locationOk && timezoneOk) {
  j.decision = 'apply_immediately';
} else if (j.taiwan_eligible === 'unclear' && j.total_score >= 85 && j.location_risk === 'medium') {
  j.decision = 'manual_check';
} else {
  // Passed every hard gate but didn't clear the auto-apply bar (e.g. score 70-84) -
  // default to manual review rather than silently dropping it.
  j.decision = 'manual_check';
}
j.why_good_fit = `${j.role_category} role, async_level=${j.async_level}, taiwan_eligible=${j.taiwan_eligible}, score=${j.total_score}`;
j.application_status = j.decision === 'apply_immediately' ? 'ready_to_apply' : 'needs_review';
return { json: j };

const j = $input.item.json;
j.cover_letter_draft = (j.content && j.content[0] && j.content[0].text) ? j.content[0].text : '';
return { json: j };

