const j = $input.item.json;
j.date_rejected = j.date_rejected || new Date().toISOString().slice(0, 10);
return { json: j };

const today = new Date().toISOString().slice(0, 10);
return $input.all()
  .filter(i => (i.json.date_found || '').slice(0, 10) === today)
  .map(i => ({ json: { ...i.json, record_type: 'filtered' } }));

const today = new Date().toISOString().slice(0, 10);
return $input.all()
  .filter(i => (i.json.date_rejected || '').slice(0, 10) === today)
  .map(i => ({ json: { ...i.json, record_type: 'rejected' } }));

const items = $input.all().map(i => i.json);
const filtered = items.filter(i => i.record_type === 'filtered');
const rejected = items.filter(i => i.record_type === 'rejected');

const top = [...filtered].sort((a, b) => (Number(b.score) || 0) - (Number(a.score) || 0)).slice(0, 5);
const manualCheck = filtered.filter(i => i.decision === 'manual_check');

const counts = { us_only: 0, eu_only: 0, hybrid: 0, timezone: 0, other: 0, low_score: 0 };
for (const r of rejected) {
  const cat = r.reject_category || 'other';
  if (counts[cat] === undefined) counts.other++;
  else counts[cat]++;
}

let lines = [];
lines.push('Daily Taiwan Eligible Async Remote Jobs');
lines.push('');
lines.push('Top jobs today:');
lines.push('');
if (top.length === 0) {
  lines.push('No jobs cleared the bar today.');
} else {
  top.forEach((j, idx) => {
    lines.push(`${idx + 1}. ${j.job_title}`);
    lines.push(`Company: ${j.company}`);
    lines.push(`Score: ${j.score}`);
    lines.push(`Taiwan eligible: ${j.taiwan_eligible}`);
    lines.push(`Reason: ${j.taiwan_reason}`);
    lines.push(`Async level: ${j.async_level}`);
    lines.push(`Timezone risk: ${j.timezone_risk}`);
    lines.push(`Salary: ${j.salary || 'not listed'}`);
    lines.push(`Why it fits Jerry: ${j.why_good_fit}`);
    lines.push(`Apply link: ${j.job_url}`);
    lines.push('');
  });
}

lines.push('Manual check:');
if (manualCheck.length === 0) {
  lines.push('None today.');
} else {
  manualCheck.forEach(j => lines.push(`- ${j.job_title} @ ${j.company} (score ${j.score}) — ${j.job_url}`));
}
lines.push('');

lines.push('Rejected summary:');
lines.push(`US only: ${counts.us_only}`);
lines.push(`EU only: ${counts.eu_only}`);
lines.push(`Hybrid/onsite: ${counts.hybrid}`);
lines.push(`Timezone risk: ${counts.timezone}`);
lines.push(`Low score: ${counts.low_score}`);
lines.push(`Other: ${counts.other}`);

return [{ json: { digest_text: lines.join('\n'), top_count: top.length, rejected_count: rejected.length } }];
